WORD_RE = re.compile(r"\w+")


def _load_wordlist() -> frozenset[str]:
    """Load word list from config file or return fallback. Words lowercased."""
    for base in (Path(__file__).resolve().parents[2] / "config", Path("config")):
        path = base / "wordlist_single_digit_rule.txt"
        if path.is_file():
            words: set[str] = set()
            for raw in path.read_text(encoding="utf-8").splitlines():
                word = raw.strip()
                if word and not word.startswith("#"):
                    words.add(word.lower())
            return frozenset(words)
    return SINGLE_DIGIT_VALID_WORD_FALLBACK


_SINGLE_DIGIT_VALID_WORDS: frozenset[str] | None = None


def get_single_digit_valid_words() -> frozenset[str]:
    """Return the word list (load once, then cached)."""
    global _SINGLE_DIGIT_VALID_WORDS  # noqa: PLW0603
    if _SINGLE_DIGIT_VALID_WORDS is None:
        _SINGLE_DIGIT_VALID_WORDS = _load_wordlist()
    return _SINGLE_DIGIT_VALID_WORDS


def _single_digit_remainder(token: str) -> str | None:
    """If token has exactly one digit, return remainder (digit removed); else None. Single pass."""
    digit_at: int | None = None
    for i, c in enumerate(token):
        if c.isdigit():
            if digit_at is not None:
                return None
            digit_at = i
    if digit_at is None:
        return None
    return token[:digit_at] + token[digit_at + 1 :]


def scan_turn_single_digit_valid_word(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (single_digit_valid_word, start_index, span, path_str) when token has one digit and remainder is in word list."""
    words = get_single_digit_valid_words()
    max_word_len = max(len(w) for w in words)
    result: list[tuple[str, int, str, str]] = []
    for m in WORD_RE.finditer(text):
        token = m.group(0)
        if len(token) < 2 or len(token) > max_word_len + 1:
            continue
        remainder = _single_digit_remainder(token)
        if remainder is not None and is_valid_word_for_rules(remainder, words):
            result.append(("single_digit_valid_word", m.start(), token, path_str))
    return result
